def check_permutation(p, N, max_rounds):
    current_guests = list(range(N))
    current_tags = {i: p[i] for i in range(N)}

    for r in range(max_rounds):
        # Step i) Any guest who has their own name tag exits the table.
        survivors = [g for g in current_guests if current_tags[g] != g]

        if not survivors:
            return False

        # Step ii) The remaining guests pass their name tags to the guest sitting immediately to their right.
        k = len(survivors)
        new_tags = {}
        for i in range(k):
            g_curr = survivors[i]
            g_next = survivors[(i + 1) % k]
            new_tags[g_next] = current_tags[g_curr]

        current_guests = survivors
        current_tags = new_tags

    return len(current_guests) > 0

def solve_all(N, max_rounds):
    count = 0
    for p in itertools.permutations(range(N)):
        if check_permutation(p, N, max_rounds):
            count += 1
    return count

